// === Tab: mySketch ===
var particles = []
var numberParticles = 5000

function setup() {
    createCanvas(windowWidth, windowHeight)
    background(0)
    angleMode(DEGREES);

    var palletes = [
        [color(247, 178, 103), color(247, 157, 101), color(244, 132, 95), color(242, 112, 89), color(242, 92, 84)],
        [color(72, 86, 150), color(231, 231, 231), color(249, 199, 132), color(252, 122, 30), color(242, 76, 0)],
        [color(19, 42, 19), color(49, 87, 44), color(79, 119, 45), color(144, 169, 85), color(236, 243, 158)],
        [color(218, 255, 125), color(178, 239, 155), color(140, 134, 170), color(129, 85, 155), color(126, 63, 143)],
        [color(127, 126, 255), color(163, 144, 228), color(198, 157, 210), color(204, 139, 140), color(198, 136, 102)],
        [color(105, 221, 255), color(150, 205, 255), color(216, 225, 255), color(219, 186, 221), color(190, 146, 162)],
        [color(141, 145, 199), color(0, 29, 61), color(0, 53, 102), color(255, 195, 0), color(255, 214, 10)]
    ]

    var color_pallete = random(palletes)

    for (let i = 0; i < numberParticles; i++) {
        particles.push(
            new Particle(
                random(windowWidth),
                random(windowHeight),
                random(color_pallete)
            )
        )
    }
}

class Particle {
    constructor(x, y, fill_color) {
        this.position = createVector(x, y)
        this.velocity = createVector(0, 0)

        this.fill_color = fill_color
    }

    update() {
        var noise_scale = 0.005
        this.steer = noise(this.position.x * noise_scale, this.position.y * noise_scale) * 360; 
        this.velocity = p5.Vector.fromAngle(this.steer);
        this.velocity.setMag(1);
        this.position.add(this.velocity);
        this.edges()
    }

    display() {
        fill(this.fill_color)
        noStroke()

        ellipse(this.position.x, this.position.y, 2)
    }

    edges() {
        if (this.position.x > windowWidth || this.position.x < 0) {
            this.position = createVector(random(windowWidth), random(windowHeight))
        }

        if (this.position.y > windowHeight || this.position.y < 0) {
            this.position = createVector(random(windowWidth), random(windowHeight))
        }
    }

}

function draw() {
    for(let i = 0; i < particles.length; i++) {
        particles[i].update()
        particles[i].display()
    }

    if(keyIsDown(32)) {
        particles = [];
        setup()
    }
}

